type ApiResponse =
  | { status: 'success'; data: string[] }
  | { status: 'error'; message: string };

function handle(res: ApiResponse) {
  switch (res.status) {           // discriminant narrows both branches
    case 'success':
      console.log(res.data.length); // res is success variant
      break;
    case 'error':
      console.error(res.message);   // res is error variant
      break;
  }
}

const isStringArray = (v: unknown): v is string[] =>
  Array.isArray(v) && v.every(x => typeof x === 'string');

function groupBy<T, K extends keyof T>(items: T[], key: K) {
  return items.reduce<Record<string, T[]>>((acc, item) => {
    const group = String(item[key]);
    (acc[group] ??= []).push(item);
    return acc;
  }, {});
}

const users = [{ role: 'admin' }, { role: 'dev' }];
groupBy(users, 'role');   // ✅ key checked against T
groupBy(users, 'age');    // ❌ compile error

